pub fn swap(s: &str, a: &str, b: &str) -> String {
    return php_strtr(s, &[(a, b), (b, a)]);
}

pub fn longest(s: &str) -> String {
    return php_strtr(s, &[("a", "1"), ("ab", "2"), ("abc", "3"), ("b", "4")]);
}

pub fn repeated(s: &str, k: &str) -> String {
    return php_strtr(s, &[(k, "first"), ("x", "X"), (&format!("{}", k), "last")]);
}

fn php_strtr(text: &str, pairs: &[(&str, &str)]) -> String {
    let mut out = String::with_capacity(text.len());
    let mut rest = text;
    while let Some(next) = rest.chars().next() {
        let longest = pairs
            .iter()
            .filter(|(key, _)| !key.is_empty() && rest.starts_with(key))
            .max_by_key(|(key, _)| key.len());
        match longest {
            Some((key, value)) => {
                out.push_str(value);
                rest = &rest[key.len()..];
            }
            None => {
                out.push(next);
                rest = &rest[next.len_utf8()..];
            }
        }
    }
    out
}

